    char s[200005][3];
    for (int i = 0; i < N; i++) {
        scanf("%2s", s[i]);
    }

    char ans[200005];

    long long a = A, b = B, c = C;

    for (int i = 0; i < N; i++) {
        int x = s[i][0] - 'A';
        int y = s[i][1] - 'A';

        long long cnt[3] = {a, b, c};

        if (cnt[x] == 0 && cnt[y] == 0) {
            printf("No\n");
            return 0;
        }

        if (cnt[x] == 0) {
            ans[i] = 'A' + x;
            cnt[x]++;
            cnt[y]--;
        } else if (cnt[y] == 0) {
            ans[i] = 'A' + y;
            cnt[y]++;
            cnt[x]--;
        } else {
            if (cnt[x] + cnt[y] == 2 && i + 1 < N) {
                int nx = s[i + 1][0] - 'A';
                int ny = s[i + 1][1] - 'A';

                if (nx == x || ny == x) {
                    ans[i] = 'A' + x;
                    cnt[x]++;
                    cnt[y]--;
                } else {
                    ans[i] = 'A' + y;
                    cnt[y]++;
                    cnt[x]--;
                }
            } else {
                ans[i] = 'A' + x;
                cnt[x]++;
                cnt[y]--;
            }
        }

        a = cnt[0];
        b = cnt[1];
        c = cnt[2];
    }

    printf("Yes\n");
    for (int i = 0; i < N; i++) {
        printf("%c\n", ans[i]);
    }

    return 0;
