int main() {
    int n;
    long long A, B, C;
    cin >> n >> A >> B >> C;

    vector<string> events(n);
    for (int i = 0; i < n; i++) cin >> events[i];

    vector<string> answers;
    bool possible = true;

    for (int i = 0; i < n; i++) {
        string s = events[i];
        bool found = false;
        // Try option 1: first char +1, second char -1
        // Try option 2: second char +1, first char -1
        auto applyOp = [&](int who_plus, int who_minus) -> bool {
            // who: 0=A,1=B,2=C
            long long vals[3] = {A, B, C};
            vals[who_plus]++;
            vals[who_minus]--;
            if (vals[0] >= 0 && vals[1] >= 0 && vals[2] >= 0) {
                A = vals[0]; B = vals[1]; C = vals[2];
                return true;
            }
            return false;
        };

        int x = (s[0] == 'A') ? 0 : (s[0] == 'B') ? 1 : 2;
        int y = (s[1] == 'A') ? 0 : (s[1] == 'B') ? 1 : 2;

        if (applyOp(x, y)) {
            answers.push_back(string(1, s[0]));
        } else if (applyOp(y, x)) {
            answers.push_back(string(1, s[1]));
        } else {
            possible = false;
            break;
        }
    }

    if (!possible) cout << "No\n";
    else {
        cout << "Yes\n";
        for (auto& a : answers) cout << a << "\n";
    }
    return 0;
}

