int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int N;
    long long A, B, C;
    cin >> N >> A >> B >> C;

    vector<string> s(N);
    for (int i = 0; i < N; ++i) cin >> s[i];

    vector<char> ans;

    auto getVal = [&](char ch) -> long long& {
        if (ch == 'A') return A;
        if (ch == 'B') return B;
        return C;
    };

    for (int i = 0; i < N; ++i) {
        char x = s[i][0], y = s[i][1];
        long long &vx = getVal(x);
        long long &vy = getVal(y);

        if (vx == 0 && vy == 0) {
            cout << "No\n";
            return 0;
        }

        if (vx == 0) {
            vx++;
            vy--;
            ans.push_back(x);
        } else if (vy == 0) {
            vy++;
            vx--;
            ans.push_back(y);
        } else {
            // both positive
            if (A + B + C == 2 && i + 1 < N) {
                // Look ahead to avoid dead end
                string t = s[i + 1];
                bool xInNext = (t[0] == x || t[1] == x);
                bool yInNext = (t[0] == y || t[1] == y);

                if (xInNext && !yInNext) {
                    vx++;
                    vy--;
                    ans.push_back(x);
                } else if (!xInNext && yInNext) {
                    vy++;
                    vx--;
                    ans.push_back(y);
                } else {
                    // arbitrary
                    vx++;
                    vy--;
                    ans.push_back(x);
                }
            } else {
                // arbitrary
                vx++;
                vy--;
                ans.push_back(x);
            }
        }
    }

    cout << "Yes\n";
    for (char c : ans) cout << c << '\n';
    return 0;
}

import java.io.*;
