public class Main {
    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        StringTokenizer st = new StringTokenizer(br.readLine());
        int N = Integer.parseInt(st.nextToken());
        int A = Integer.parseInt(st.nextToken());
        int B = Integer.parseInt(st.nextToken());
        int C = Integer.parseInt(st.nextToken());

        String[] events = new String[N];
        for (int i = 0; i < N; i++) {
            events[i] = br.readLine().trim();
        }

        StringBuilder sb = new StringBuilder();
        boolean possible = true;

        for (int i = 0; i < N; i++) {
            String s = events[i];
            char x = s.charAt(0);
            char y = s.charAt(1);

            // Get current values
            int valX = getValue(x, A, B, C);
            int valY = getValue(y, A, B, C);

            // Decide which to increment
            if (valX == 0 && valY == 0) {
                possible = false;
                break;
            } else if (valX == 0) {
                // Must increment X, decrement Y
                sb.append(x).append("\n");
                if (x == 'A') A++;
                else if (x == 'B') B++;
                else C++;
                if (y == 'A') A--;
                else if (y == 'B') B--;
                else C--;
            } else if (valY == 0) {
                // Must increment Y, decrement X
                sb.append(y).append("\n");
                if (y == 'A') A++;
                else if (y == 'B') B++;
                else C++;
                if (x == 'A') A--;
                else if (x == 'B') B--;
                else C--;
            } else {
                // Both positive, check future constraints
                // Look ahead: if next event involves the variable we might decrement to zero,
                // prefer incrementing the one that won't cause future issues.
                // Simple heuristic: always increment the larger one to keep balance
                if (valX >= valY) {
                    sb.append(x).append("\n");
                    if (x == 'A') A++;
                    else if (x == 'B') B++;
                    else C++;
                    if (y == 'A') A--;
                    else if (y == 'B') B--;
                    else C--;
                } else {
                    sb.append(y).append("\n");
                    if (y == 'A') A++;
                    else if (y == 'B') B++;
                    else C++;
                    if (x == 'A') A--;
                    else if (x == 'B') B--;
                    else C--;
                }
            }
        }

        if (possible) {
            System.out.println("Yes");
            System.out.print(sb.toString());
        } else {
            System.out.println("No");
        }
    }

    private static int getValue(char var, int A, int B, int C) {
        switch (var) {
            case 'A': return A;
            case 'B': return B;
            case 'C': return C;
            default: return 0;
        }
    }
}

