public class Main {
    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        StringTokenizer st = new StringTokenizer(br.readLine());
        long A = Long.parseLong(st.nextToken());
        long B = Long.parseLong(st.nextToken());
        long C = Long.parseLong(st.nextToken());
        int N = Integer.parseInt(br.readLine().trim());
        String[] events = new String[N];
        for (int i = 0; i < N; i++) events[i] = br.readLine().trim();

        StringBuilder sb = new StringBuilder();
        long[] vars = {A, B, C};
        // AB=0,1; AC=0,2; BC=1,2
        for (int i = 0; i < N; i++) {
            String s = events[i];
            int x = s.charAt(0) - 'A', y = s.charAt(1) - 'A';
            // option1: vars[x]++, vars[y]--  requires vars[y]>=1
            // option2: vars[x]--, vars[y]++  requires vars[x]>=1
            boolean opt1 = vars[y] >= 1, opt2 = vars[x] >= 1;
            if (!opt1 && !opt2) { System.out.println("No"); return; }
            boolean choose1;
            if (opt1 && !opt2) choose1 = true;
            else if (!opt1 && opt2) choose1 = false;
            else choose1 = vars[x] <= vars[y]; // increase the smaller
            if (choose1) { vars[x]++; vars[y]--; sb.append(s.charAt(0)).append('\n'); }
            else { vars[x]--; vars[y]++; sb.append(s.charAt(1)).append('\n'); }
        }
        System.out.println("Yes");
        System.out.print(sb);
    }
}

import java.io.*;
import java.util.*;

public class Main {
    static class FastScanner {
        private final InputStream in = System.in;
        private final byte[] buffer = new byte[1 << 16];
        private int ptr = 0, len = 0;

        private int read() throws IOException {
            if (ptr >= len) {
                len = in.read(buffer);
                ptr = 0;
                if (len <= 0) return -1;
            }
            return buffer[ptr++];
        }

        String next() throws IOException {
            StringBuilder sb = new StringBuilder();
            int c;
            do {
                c = read();
            } while (c <= ' ' && c != -1);
            while (c > ' ') {
                sb.append((char) c);
                c = read();
            }
            return sb.toString();
        }

        int nextInt() throws IOException {
            return Integer.parseInt(next());
        }
    }

    static int idx(char ch) {
        if (ch == 'A') return 0;
        if (ch == 'B') return 1;
        return 2;
    }

    public static void main(String[] args) throws Exception {
        FastScanner fs = new FastScanner();

        int N = fs.nextInt();
        int[] x = new int[3];
        x[0] = fs.nextInt();
        x[1] = fs.nextInt();
        x[2] = fs.nextInt();

        String[] s = new String[N];
        for (int i = 0; i < N; i++) s[i] = fs.next();

        List<Character> ans = new ArrayList<>();

        for (int i = 0; i < N; i++) {
            int p = idx(s[i].charAt(0));
            int q = idx(s[i].charAt(1));

            if (x[p] == 0 && x[q] == 0) {
                System.out.println("No");
                return;
            }

            int chosenIncrease;

            if (x[p] == 0) {
                chosenIncrease = p;
            } else if (x[q] == 0) {
                chosenIncrease = q;
            } else if (x[p] == 1 && x[q] == 1 && i + 1 < N) {
                int np = idx(s[i + 1].charAt(0));
                int nq = idx(s[i + 1].charAt(1));
                if (np == p || nq == p) {
                    chosenIncrease = p;
                } else {
                    chosenIncrease = q;
                }
            } else {
                if (x[p] <= x[q]) chosenIncrease = p;
                else chosenIncrease = q;
            }

            int chosenDecrease = (chosenIncrease == p ? q : p);

            x[chosenIncrease]++;
            x[chosenDecrease]--;

            ans.add(chosenIncrease == 0 ? 'A' : chosenIncrease == 1 ? 'B' : 'C');
        }

        System.out.println("Yes");
        StringBuilder sb = new StringBuilder();
        for (char c : ans) sb.append(c).append('\n');
        System.out.print(sb.toString());
    }
}
